* { box-sizing: border-box; }
:root { color-scheme: light; font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 16px; background: #172a35; color: #20323b; }
body { min-width: 320px; min-height: 100vh; margin: 0; padding: 32px 16px; display: grid; place-items: center; background: radial-gradient(ellipse at 50% 0%, #31505a 0, #172a35 68%); }
.app-card { width: min(100%, 480px); padding: 32px; border: 1px solid #d9e5df; border-radius: 24px; background: #f7f8f1; box-shadow: 0 24px 60px #0b192066; }
.heading { text-align: center; }
.eyebrow { margin: 0 0 8px; color: #52736d; font-size: .8rem; font-weight: 800; letter-spacing: .13em; }
h1 { margin: 0; color: #20323b; font-size: clamp(2rem, 8vw, 2.7rem); line-height: 1.1; }
.intro { margin: 10px 0 24px; color: #52646a; }
.board-wrap { padding: 12px; border: 1px solid #d9e5df; border-radius: 18px; background: #e9efe6; }
.grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 6px; aspect-ratio: 1; }
.cell { display: grid; place-items: center; min-width: 0; border: 1px solid #d6e0d7; border-radius: 9px; background: #fffef9; }
.robot { width: 58%; height: 58%; display: grid; place-items: center; border: 2px solid #20323b; border-radius: 7px; background: #e5a94c; color: #20323b; font-size: clamp(1.35rem, 7vw, 2rem); font-weight: 900; line-height: 1; transition: transform 160ms ease; }
.status { display: grid; grid-template-columns: 1fr 1fr; gap: 12px; margin: 18px 0; }
.status > div { display: grid; gap: 4px; padding: 12px 14px; border-radius: 12px; background: #e9efe6; }
.status-label { color: #62736e; font-size: .75rem; font-weight: 800; letter-spacing: .08em; }
.status strong { font-size: 1rem; }
.controls { display: grid; gap: 10px; }
.turn-controls { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.button, .reset-button { min-height: 48px; padding: 10px 14px; border: 1px solid #aebfb5; border-radius: 12px; background: #fffef9; color: #20323b; font: inherit; font-weight: 700; cursor: pointer; transition: background 120ms ease, transform 120ms ease, box-shadow 120ms ease; }
.button span { margin-left: 5px; font-size: 1.1em; }
.button-primary { border-color: #285c56; background: #285c56; color: #fffef9; }
.button:hover, .reset-button:hover { background: #e5eee6; }
.button-primary:hover { background: #1f4c47; }
.button:active, .reset-button:active { transform: translateY(1px) scale(.99); }
.button:focus-visible, .reset-button:focus-visible { outline: 3px solid #e5a94c; outline-offset: 3px; }
.reset-button { border-color: transparent; background: transparent; color: #52646a; }
.hint { margin: 16px 0 0; color: #62736e; text-align: center; font-size: .9rem; }
@media (max-width: 400px) { body { padding: 16px 12px; } .app-card { padding: 22px 18px; border-radius: 20px; } .board-wrap { padding: 8px; } .grid { gap: 4px; } .cell { border-radius: 7px; } .status { gap: 8px; } .status > div { padding: 10px; } }
@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition-duration: .01ms !important; } }

const grid = document.querySelector("#grid");
const positionText = document.querySelector("#position");
const directionText = document.querySelector("#direction");
const directions = [
  { name: "Right", arrow: "→", row: 0, col: 1 },
  { name: "Down", arrow: "↓", row: 1, col: 0 },
  { name: "Left", arrow: "←", row: 0, col: -1 },
  { name: "Up", arrow: "↑", row: -1, col: 0 }
];
let row = 0;
let col = 0;
let facing = 0;

function render() {
  grid.replaceChildren();
  for (let r = 0; r < 5; r += 1) {
    for (let c = 0; c < 5; c += 1) {
      const cell = document.createElement("div");
      cell.className = "cell";
      if (r === row && c === col) {
        const robot = document.createElement("span");
        robot.className = "robot";
        robot.textContent = directions[facing].arrow;
        robot.setAttribute("aria-hidden", "true");
        cell.append(robot);
      }
      grid.append(cell);
    }
  }
  const direction = directions[facing];
  positionText.textContent = `Row ${row + 1}, Column ${col + 1}`;
  directionText.textContent = `${direction.name} ${direction.arrow}`;
  grid.setAttribute("aria-label", `5 by 5 grid. Robot at row ${row + 1}, column ${col + 1}, facing ${direction.name}.`);
}

function moveForward() {
  const nextRow = row + directions[facing].row;
  const nextCol = col + directions[facing].col;
  if (nextRow >= 0 && nextRow < 5 && nextCol >= 0 && nextCol < 5) {
    row = nextRow;
    col = nextCol;
  }
  render();
}
function turnLeft() { facing = (facing + 3) % 4; render(); }
function turnRight() { facing = (facing + 1) % 4; render(); }
function reset() { row = 0; col = 0; facing = 0; render(); }

document.querySelector("#forward").addEventListener("click", moveForward);
document.querySelector("#left").addEventListener("click", turnLeft);
document.querySelector("#right").addEventListener("click", turnRight);
document.querySelector("#reset").addEventListener("click", reset);
document.addEventListener("keydown", (event) => {
  if (event.altKey || event.ctrlKey || event.metaKey || /^(INPUT|TEXTAREA|SELECT)$/.test(event.target.tagName)) return;
  if (event.key === "ArrowUp") { event.preventDefault(); moveForward(); }
  else if (event.key === "ArrowLeft") { event.preventDefault(); turnLeft(); }
  else if (event.key === "ArrowRight") { event.preventDefault(); turnRight(); }
  else if (event.key.toLowerCase() === "r") reset();
});
render();
